			       "process_bitmap_updates(), invalid bitmap dimensions %dx%d bpp=%d",
			       width, height, bpp);
			continue;
		}

		if (!compress)
		{
			int y;
			bmpdata = (uint8 *) xmalloc((size_t) width * height * Bpp);
			for (y = 0; y < height; y++)
			{
				in_uint8a(s, &bmpdata[(height - y - 1) * (width * Bpp)],
					  width * Bpp);
			}
			ui_paint_bitmap(left, top, cx, cy, width, height, bmpdata);
			xfree(bmpdata);
			continue;
		}


		if (compress & 0x400)
		{
			size = bufsize;
		}
		else
		{
			in_uint8s(s, 2);	/* pad */
			in_uint16_le(s, size);
			in_uint8s(s, 4);	/* line_size, final_size */
		}
		in_uint8p(s, data, size);
		bmpdata = (uint8 *) xmalloc((size_t) width * height * Bpp);
		if (bitmap_decompress(bmpdata, width, height, data, size, Bpp))
		{
			ui_paint_bitmap(left, top, cx, cy, width, height, bmpdata);
		}
		else
		{
			logger(Graphics, Warning,
			       "process_bitmap_updates(), failed to decompress bitmap");
		}

		xfree(bmpdata);
	}
}", "explanation": "The original code computed the allocation size as width * height * Bpp using 16-bit arithmetic, which can overflow and cause a heap buffer overflow when reading bitmap data. The fix validates that width, height, and Bpp are nonzero and casts the multiplication to size_t so the allocation size is computed without integer overflow."}

