							GetPayloadTime(handle, payloadpos, &in, &out);
							meanX += out;
						}
						else
						{
							uint32_t repeat = GPMF_Repeat(ms);
							samples += repeat;

							float in, out;

							repeatarray[payloadpos] = samples;
							meanY += (double)samples;

							GetPayloadTime(handle, payloadpos, &in, &out);
							meanX += out;
